//! A snapshot with its catalog and statistics.
struct RESTSnapshotData {
	//! The snapshot.
	DuckLakeSnapshot snapshot;
	//! The catalog of the snapshot.
	unique_ptr<DuckLakeCatalogInfo> catalog;
	//! The statistics of the tables of the snapshot.
	RESTOptional<vector<DuckLakeGlobalStatsInfo>> stats;
};

//! What a request for a snapshot returns besides the snapshot.
struct RESTSnapshotIncludes {
	//! Return the catalog of the snapshot.
	bool include_catalog = false;
	//! Return the table statistics of the snapshot.
	bool include_stats = false;
	//! The schema version of the latest catalog the client has loaded. If the snapshot has a different schema
	optional_idx cached_metadata_version;
	//! The next file id of the snapshot of the latest statistics the client has loaded. If the snapshot has a
	optional_idx cached_data_version;
};

//! The snapshot that a request reads. A `snapshot` is used as-is, which also allows reading at snapshots that
struct RESTSnapshotReference {
	//! The snapshot, as returned by `snapshots/latest` and `snapshots/at`.
	DuckLakeSnapshot snapshot;
	//! The id of the snapshot.
	optional_idx snapshot_id;
};

struct RESTConfigRequest {
	//! The name that the catalog is served under. The catalog of the server if it serves exactly one.
	string catalog_name;
};

struct RESTConfigResponse {
	//! Properties that the client uses if it has no value for them.
	map<string, string> defaults;
	//! Properties that the client uses instead of its own values, e.g. `prefix`.
	map<string, string> overrides;
	//! The requests that the server supports.
	vector<string> endpoints;
};

struct RESTGetLatestSnapshotRequest : public RESTSnapshotIncludes {};

struct RESTGetMetadataRequest {};

struct RESTGetSnapshotAtRequest : public RESTSnapshotIncludes {
	//! The unit of the value of the `AT` clause.
	string unit;
	//! The snapshot id or the name of a snapshot tag (for `version`), or the timestamp (for `timestamp`).
	string value;
	//! Whether a timestamp finds the last snapshot before or the first snapshot after it.
	string bound = string("upper");
	//! The newest snapshot that the clause can find, snapshots committed after a client's transaction started are
	optional_idx newest_snapshot_id;
};

struct RESTListSnapshotsRequest {
	//! Exclude the latest snapshot.
	bool exclude_latest = false;
	//! Only snapshots created before this timestamp.
	string older_than;
	//! Only these snapshots.
	RESTOptional<vector<idx_t>> snapshot_ids;
	//! The maximum number of entries to return. The server picks a number if absent, and can return fewer entries.
	optional_idx page_size;
	//! The `next_page_token` of the previous page. The first page if absent.
	string page_token;
};

struct RESTListSnapshotsResponse {
	//! The snapshots, ordered by their ids.
	vector<DuckLakeSnapshotInfo> snapshots;
	//! The token of the next page, absent on the last page.
	string next_page_token;
};

struct RESTSelectRequest : public RESTSnapshotReference {
	//! The table to scan.
	idx_t table_id = 0;
	//! A page token of an earlier response: returns that page of files. The request has no other members then.
	string page_token;
	//! Aggregates over the whole table that the server answers from statistics if it can. Not with `filters`.
	vector<RESTAggregate> aggregates;
	//! Return the extended file list used to plan deletes and updates in `extended_files`, instead of `files`.
	bool extended = false;
	//! Filters to prune files with.
	unique_ptr<RESTScanFilters> filters;
	//! The ids of the column mappings that the client has: the response only has the other column mappings that its
	set<idx_t> known_column_mappings;
	//! The columns that the client reads. The inlined rows only have these columns, besides the row id and the
	RESTOptional<vector<RESTColumnIdentifier>> columns;
};

struct RESTSelectResponse {
	//! The files of the scan.
	vector<DuckLakeFileListEntry> files;
	//! The files of the scan, for `extended` scans.
	vector<DuckLakeFileListExtendedEntry> extended_files;
	//! The inlined rows of the table, absent if it has no inlined data.
	unique_ptr<RESTInlinedRows> inlined_data;
	//! The tokens of the other pages of the files of the scan, if there are many. The files of the scan are the files
	vector<string> page_tokens;
	//! The results of the `aggregates` of the request, in their order.
	vector<RESTAggregateResult> aggregate_results;
	//! The column mappings that the files of the response refer to (by their `mapping_id`), and that the client does
	vector<DuckLakeColumnMappingInfo> column_mappings;
};

struct RESTTableChangesRequest : public RESTSnapshotReference {
	//! The table. The snapshot is the last snapshot of the range.
	idx_t table_id = 0;
	//! The first snapshot of the range.
	DuckLakeSnapshot start_snapshot;
	//! The id of the first snapshot of the range.
	optional_idx start_snapshot_id;
	//! A page token of an earlier response: returns that page of files. The request has no other members then.
	string page_token;
	//! The changes to return. Required, unless the request has a `page_token`.
	string changes;
	//! The ids of the column mappings that the client has: the response only has the other column mappings that its
	set<idx_t> known_column_mappings;
	//! The columns that the client reads. The inlined rows only have these columns, besides the row id and the
	RESTOptional<vector<RESTColumnIdentifier>> columns;
};

struct RESTTableChangesResponse {
	//! For `insertions`: the files with inserted rows.
	vector<DuckLakeFileListEntry> insertions;
	//! For `deletions`: the files with deleted rows.
	vector<DuckLakeDeleteScanEntry> deletions;
	//! The inlined rows that changed, absent if the table has no inlined data.
	unique_ptr<RESTInlinedRows> inlined_data;
	//! The tokens of the other pages of the files, see `scan`.
	vector<string> page_tokens;
	//! The column mappings that the files of the response refer to (by their `mapping_id`), and that the client does
	vector<DuckLakeColumnMappingInfo> column_mappings;
};

struct RESTCompactRequest {
	//! The type of the compaction.
	string type;
	//! The schema of `table_name`, the default schema if absent. For `flush_inlined_data`, all tables of the schema
	string schema_name;
	//! Only compact this table, all tables if absent.
	string table_name;
	//! The maximum number of files to compact.
	optional_idx max_compacted_files;
	//! For `merge_adjacent`: only merge files of at least this size.
	optional_idx min_file_size;
	//! For `merge_adjacent`: only merge files of at most this size.
	optional_idx max_file_size;
	//! For `merge_adjacent`: only merge files written after this timestamp.
	string newer_than;
	//! For `merge_adjacent`: only merge files written before this timestamp.
	string older_than;
	//! For `rewrite_delete`: the fraction of deleted rows above which files are rewritten.
	RESTOptional<double> delete_threshold;
};

struct RESTCompactResponse {
	//! The compactions that were performed, per table.
	vector<RESTCompactionResult> results;
};

struct RESTCommitTransactionRequest : public RESTSnapshotReference {
	//! The commit information of the snapshot.
	unique_ptr<DuckLakeSnapshotCommit> commit_info;
	//! How the server retries the commit on conflicts.
	unique_ptr<RESTRetryConfig> retry;
	//! The changes, applied in order, e.g. `[{"create_table": {...}}, {"insert_rows": {...}}]`.
	vector<unique_ptr<RESTCommitRequest>> requests;
};

struct RESTCommitTransactionResponse {
	//! The committed snapshot, absent if the requests did not create a snapshot (e.g. if they only set options).
	DuckLakeSnapshot snapshot;
	//! The entries the transaction created, with the ids the commit gave them.
	vector<RESTCreatedEntry> entry_ids;
	//! The options of the tables the transaction created or altered, with the ids the commit gave the tables.
	vector<RESTOptionSetting> table_options;
};

